package generate_jwt_test

import (
	"context"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/stretchr/testify/require"

	"github.com/isaac-olle/gas-backoffice/internal/bounded_contexts/security/key_pairs"
)

// stubPrivKeyHex and stubPubKeyHex are valid hex-encoded RSA 2048-bit DER keys.
const stubPrivKeyHex = ""
const stubPubKeyHex = ""

// mockTokenGenerator stubs the JWT token generator.
type mockTokenGenerator struct {
	token      string
	err        error
	gotKeyPair *key_pairs.KeyPair
	gotClaims  map[string]any
}

func (m *mockTokenGenerator) Generate(_ context.Context, claims map[string]any, kp *key_pairs.KeyPair, _ time.Duration) (string, error) {
	m.gotKeyPair = kp
	m.gotClaims = claims
	return m.token, m.err
}

// newKeyPairMother builds a valid KeyPair with fresh random IDs.
func newKeyPairMother(t *testing.T) *key_pairs.KeyPair {
	t.Helper()
	kp, err := key_pairs.NewKeyPair(
		uuid.New().String(),
		uuid.New().String(),
		"RS256",
		stubPrivKeyHex,
		stubPubKeyHex,
	)
	require.NoError(t, err)
	return kp
}
